#!/usr/bin/env node
/**
 * Write the relay's bundle (`relay/generated/bundle.js`) from the web app's
 * sources: the wire protocol shared with the tab
 * (`assets/js/app/agent/bridge/relay-protocol.js`: the wire, the bounds of a
 * result, the view card's resource), the action catalogue as
 * MCP tools (what `tools/list` answers while no tab is connected), the agent
 * instructions, the Cellucid version and the page's canonical origin
 * (`index.html`).
 *
 *   node scripts/generate-relay-bundle.mjs           # write it
 *   node scripts/generate-relay-bundle.mjs --check   # exit 1 when it is stale
 *
 * `tests/relay-bundle-contract.test.mjs` fails while the committed bundle
 * differs from what this writes, so an action added, a parameter changed, a
 * version bumped or an instruction edited cannot leave the relay behind.
 */

import { createHash } from 'node:crypto';
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { catalogDocument, createActionCatalog } from '../assets/js/app/actions/catalog.js';
import { ACTION_DEFINITIONS } from '../assets/js/app/actions/definitions/index.js';
import { mcpToolsOf } from '../assets/js/app/agent/bridge/mcp-tools.js';
import { instructionsFor } from '../assets/js/app/agent/instructions.js';
import {
  CONNECT_CODE_ALPHABET,
  CONNECT_CODE_LENGTH,
  CONNECT_FRAGMENT_KEY,
  RELAY_CLOSE,
  RELAY_PING,
  RELAY_PONG,
  RELAY_PROTOCOL_VERSION,
  RELAY_SECRET_PREFIX,
  RELAY_STATUS_TOOL,
  RELAY_SUBPROTOCOL,
  RESULT_DATA_TAGS,
  RESULT_IMAGE_MAX_BYTES,
  RESULT_IMAGE_MAX_SIDE,
  RESULT_TEXT_CHARS,
  TAB_SECRET_PATTERN,
  VIEW_APP,
} from '../assets/js/app/agent/bridge/relay-protocol.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
export const RELAY_BUNDLE_PATH = path.join(ROOT, 'relay', 'generated', 'bundle.js');

function only(pattern, text, what) {
  const matches = [...text.matchAll(pattern)];
  if (matches.length !== 1) throw new Error(`index.html must have exactly one ${what}`);
  return matches[0][1];
}

/** The bundle's text, as this checkout's sources make it. */
export async function renderRelayBundle() {
  const index = await readFile(path.join(ROOT, 'index.html'), 'utf8');
  const appVersion = only(/<meta name="cellucid-version" content="([^"]+)" \/> <!-- CELLUCID_VERSION -->/g, index, 'version meta');
  const appOrigin = new URL(only(/<link rel="canonical" href="([^"]+)" \/>/g, index, 'canonical link')).origin;
  const document = catalogDocument(createActionCatalog(ACTION_DEFINITIONS));
  const bundle = {
    appVersion,
    appOrigin,
    catalogDigest: `sha256-${createHash('sha256').update(JSON.stringify(document)).digest('hex')}`,
    protocol: {
      version: RELAY_PROTOCOL_VERSION,
      subprotocol: RELAY_SUBPROTOCOL,
      secretPrefix: RELAY_SECRET_PREFIX,
      tabSecretPattern: TAB_SECRET_PATTERN.source,
      ping: RELAY_PING,
      pong: RELAY_PONG,
      close: { ...RELAY_CLOSE },
      resultTextChars: RESULT_TEXT_CHARS,
      resultData: { ...RESULT_DATA_TAGS },
      resultImageMaxBytes: RESULT_IMAGE_MAX_BYTES,
      resultImageMaxSide: RESULT_IMAGE_MAX_SIDE,
      viewApp: { ...VIEW_APP, tools: [...VIEW_APP.tools] },
      connectCode: { alphabet: CONNECT_CODE_ALPHABET, length: CONNECT_CODE_LENGTH },
      connectFragmentKey: CONNECT_FRAGMENT_KEY,
    },
    statusTool: RELAY_STATUS_TOOL,
    instructions: instructionsFor('connector'),
    tools: mcpToolsOf(document),
  };
  return `// Generated by scripts/generate-relay-bundle.mjs from the web app's sources. Do not edit:
// run \`node scripts/generate-relay-bundle.mjs\` (tests/relay-bundle-contract.test.mjs checks it).

function frozen(value) {
  if (value !== null && typeof value === 'object') {
    for (const item of Object.values(value)) frozen(item);
    Object.freeze(value);
  }
  return value;
}

export const RELAY_BUNDLE = frozen(${JSON.stringify(bundle, null, 2)});
`;
}

async function main() {
  const text = await renderRelayBundle();
  const relative = path.relative(ROOT, RELAY_BUNDLE_PATH);
  if (process.argv.includes('--check')) {
    let current = null;
    try {
      current = await readFile(RELAY_BUNDLE_PATH, 'utf8');
    } catch {
      current = null;
    }
    if (current !== text) {
      console.error(`${relative} is stale: run node scripts/generate-relay-bundle.mjs`);
      process.exitCode = 1;
      return;
    }
    console.log(`${relative} is current`);
    return;
  }
  await writeFile(RELAY_BUNDLE_PATH, text);
  console.log(`wrote ${relative}`);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await main();
}
